name: PR Docs Preview

on:
  pull_request:
    types: [opened, synchronize, reopened, closed]

jobs:
  preview:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          token: ${{ secrets.GITHUB_TOKEN }}

      - name: Set up Python
        uses: actions/setup-python@v5
        with:
          python-version: '3.11'

      - name: Install dependencies
        run: |
          python -m pip install --upgrade pip
          pip install mike mkdocs

      - name: Configure git
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"

      - name: Deploy PR preview
        if: github.event.action != 'closed'
        run: |
          mike deploy --push --branch=gh-pages --config-file=mkdocs.yml --version=pr/${{ github.event.pull_request.number }} --message="PR preview ${{ github.event.pull_request.number }}"

      - name: Delete PR preview
        if: github.event.action == 'closed'
        run: |
          mike delete --push pr/${{ github.event.pull_request.number }}

      - name: Get changed docs URLs
        if: github.event.action != 'closed'
        id: changed_urls
        run: |
          urls=$(python scripts/get_changed_docs_urls.py)
          echo "urls=$urls" >> $GITHUB_OUTPUT

      - name: Post or update preview comment
        if: github.event.action != 'closed'
        uses: actions/github-script@v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = ${{ github.event.pull_request.number }};
            const previewUrl = `https://docs.sleap.ai/pr/${prNumber}/`;
            const changedUrls = `${{ steps.changed_urls.outputs.urls }}`.trim();
            const bodyLines = [];
            bodyLines.push(`**Preview URL**: ${previewUrl}`);
            if (changedUrls) {
              bodyLines.push(`**Changed pages**:`);
              bodyLines.push(changedUrls.split('\n').map(u => `- ${u}`).join('\n'));
            }
            const body = bodyLines.join('\n\n');
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
            });
            const botComment = comments.find(c => c.user.login === context.actor && c.body.includes('Preview URL'));
            if (botComment) {
              await github.rest.issues.updateComment({
                comment_id: botComment.id,
                body,
              });
            } else {
              await github.rest.issues.createComment({
                issue_number: prNumber,
                body,
              });
            }
